sqlMap.select:
SELECT COUNT(*) FROM PA_DIFFERENCE_PERSONNEL T,
( SELECT #PA_MONTH:VARCHAR# AS PA_MONTH, HR.EMPID FROM HR_EMPLOYEE HR, HR_DEPARTMENT HD WHERE HR.DEPTID = HD.DEPTID
)
( SELECT HR.PA_MONTH, HR.EMPID, HR.CHINESENAME, HR.PINYINNAME AS CHINESE_PINYIN, HR.DEPTID FROM PA_HISTORY HR WHERE HR.PA_MONTH = #PA_MONTH:VARCHAR#
)
EMP_INFO WHERE T.EMPID = EMP_INFO.EMPID AND T.PA_MONTH = #PA_MONTH:VARCHAR#
